#pragma once

/**
 * @file ApplicationMetal.hpp
 * @brief Platform bridge between ImGuiApplication and the macOS Metal renderer.
 *
 * This interface is intentionally opaque to the C++ application layer. The
 * implementation owns all Objective-C and Metal objects and is compiled only
 * for macOS, while the rest of ImGuiApplication remains platform-independent.
 *
 * @note Generated by GPT-5.6 Luna (GitHub Copilot).
 */

struct GLFWwindow;
struct ImDrawData;

/**
 * @brief Creates the Metal renderer for a GLFW Cocoa window.
 *
 * The function creates the system Metal device and command queue, attaches a
 * CAMetalLayer to the native Cocoa view, and initializes the Dear ImGui Metal
 * backend. The returned pointer must be released with
 * ImGuiApplicationMetal_Destroy().
 *
 * @param window A valid GLFW window created with GLFW_NO_API.
 * @return An opaque renderer handle, or `nullptr` if Metal initialization
 *         fails.
 */
void* ImGuiApplicationMetal_Create(GLFWwindow* window);

/**
 * @brief Releases the Metal renderer and shuts down the ImGui Metal backend.
 *
 * Any command encoder still owned by the renderer is finished before the
 * renderer is destroyed. Passing `nullptr` is safe.
 *
 * @param renderer Opaque handle returned by ImGuiApplicationMetal_Create().
 */
void ImGuiApplicationMetal_Destroy(void* renderer);

/**
 * @brief Acquires the next drawable and begins a Metal render pass.
 *
 * This function must be called once before ImGui::NewFrame(). It also informs
 * the ImGui Metal backend about the current render-pass pixel format. The
 * matching ImGuiApplicationMetal_RenderFrame() call ends the encoder and
 * submits the command buffer.
 *
 * @param renderer Opaque renderer handle.
 * @param window The GLFW window whose framebuffer size controls the drawable.
 * @return `true` when a drawable, command buffer, and command encoder are
 *         ready; `false` when the window is minimized or a drawable is not
 *         available.
 */
bool ImGuiApplicationMetal_BeginFrame(void* renderer, GLFWwindow* window);

/**
 * @brief Renders ImGui draw data and submits the current Metal frame.
 *
 * This function must be called after ImGui::Render() and a successful
 * ImGuiApplicationMetal_BeginFrame(). It ends the command encoder, presents
 * the drawable, and commits the command buffer.
 *
 * @param renderer Opaque renderer handle.
 * @param drawData Draw data produced by ImGui::Render().
 */
void ImGuiApplicationMetal_RenderFrame(void* renderer, ImDrawData* drawData);
